//! Byte-for-byte interop tests for the payload codecs.
//!
//! The decode vectors are the exact bytes the Go server's `CompressPayload`
//! produced for known payloads at the pinned release (generated by
//! `cmd/compvec`). Decoding them here proves the Rust decoders read what the
//! Go encoder writes — the download direction — for each format. The plaintext
//! is regenerated rather than embedded, so only the small compressed blobs are
//! hard-coded.

use super::*;

/// The 55-byte seed the vector generator cycled to build its text payloads.
const SEED: &[u8] = b"the quick brown fox jumps over the lazy dog 0123456789 ";

/// Rebuild the `repeated_1k` payload: `SEED` cycled to 1024 bytes.
fn repeated_1k() -> Vec<u8> {
    (0..1024).map(|i| SEED[i % SEED.len()]).collect()
}

/// Rebuild the `binary_ramp` payload: 2000 bytes of `(i*7) % 251`.
fn binary_ramp() -> Vec<u8> {
    (0..2000usize).map(|i| ((i * 7) % 251) as u8).collect()
}

fn unhex(s: &str) -> Vec<u8> {
    hex::decode(s).expect("vector is valid hex")
}

// Go `CompressPayload` output for `repeated_1k`, one per codec.
const ZSTD_REPEATED_1K: &str = "28b52ffd440800030d0200740374686520717569636b2062726f776e20666f78206a756d7073206f76657220746865206c617a7920646f67203031323334353637383920015418052d675c079ea37977";
const LZ4_REPEATED_1K: &str = "00040000ff2874686520717569636b2062726f776e20666f78206a756d7073206f76657220746865206c617a7920646f672030313233343536373839203700ffffffa500de0300de03c06d7073206f76657220746865";
const ZLIB_REPEATED_1K: &str = "2ac94855282ccd4cce56482aca2fcf5348cbaf50c82acd2d2856c82f4b2d5228c94855c849acaa5448c94f573030343236313533b7b05418d536aa6d54db30d0061800";

// Go `CompressPayload` output for the 2000-byte `binary_ramp`, ZSTD (the
// shipping default codec) — a non-text payload with different back-references.
const ZSTD_BINARY_RAMP: &str = "";

#[test]
fn decodes_go_zstd_output() {
    let want = repeated_1k();
    let input = unhex(ZSTD_REPEATED_1K);
    let got = try_decompress_payload(&input, TYPE_ZSTD).unwrap();
    assert_eq!(got.as_ref(), want.as_slice());

    let ramp = binary_ramp();
    let input = unhex(ZSTD_BINARY_RAMP);
    let got = try_decompress_payload(&input, TYPE_ZSTD).unwrap();
    assert_eq!(got.as_ref(), ramp.as_slice());
}

#[test]
fn decodes_go_lz4_output() {
    let want = repeated_1k();
    let input = unhex(LZ4_REPEATED_1K);
    let got = try_decompress_payload(&input, TYPE_LZ4).unwrap();
    assert_eq!(got.as_ref(), want.as_slice());
}

#[test]
fn decodes_go_zlib_output() {
    let want = repeated_1k();
    let input = unhex(ZLIB_REPEATED_1K);
    let got = try_decompress_payload(&input, TYPE_ZLIB).unwrap();
    assert_eq!(got.as_ref(), want.as_slice());
}

#[test]
fn round_trips_every_codec_on_text_and_binary() {
    for &codec in &[TYPE_ZSTD, TYPE_LZ4, TYPE_ZLIB] {
        for payload in [repeated_1k(), binary_ramp()] {
            let (packed, used) = compress_payload(&payload, codec, DEFAULT_MIN_SIZE);
            // Both payloads are compressible, so the codec must have been used.
            assert_eq!(used, codec, "codec {codec} should have compressed");
            assert!(packed.len() < payload.len(), "codec {codec} should shrink");
            let back = try_decompress_payload(&packed, used).unwrap();
            assert_eq!(
                back.as_ref(),
                payload.as_slice(),
                "codec {codec} round-trip"
            );
        }
    }
}

#[test]
fn our_lz4_block_is_the_go_header_shape() {
    // The 4-byte little-endian length header must carry the uncompressed size,
    // so a Go `UncompressBlock` can size its buffer. Verify the header, then
    // that our own decoder reverses it.
    let payload = repeated_1k();
    let (packed, used) = compress_payload(&payload, TYPE_LZ4, DEFAULT_MIN_SIZE);
    assert_eq!(used, TYPE_LZ4);
    let header = u32::from_le_bytes([packed[0], packed[1], packed[2], packed[3]]);
    assert_eq!(header as usize, payload.len());
}

#[test]
fn empty_and_small_and_off_are_passthrough() {
    // Empty input: off, unchanged.
    let (out, used) = compress_payload(&[], TYPE_ZSTD, DEFAULT_MIN_SIZE);
    assert_eq!(used, TYPE_OFF);
    assert!(out.is_empty());

    // At or below the min size: not worth compressing.
    let small = b"too short to bother compressing";
    assert!(small.len() < DEFAULT_MIN_SIZE);
    let (out, used) = compress_payload(small, TYPE_ZSTD, DEFAULT_MIN_SIZE);
    assert_eq!(used, TYPE_OFF);
    assert_eq!(out.as_ref(), small.as_slice());

    // Codec off: pass through whatever the size.
    let big = repeated_1k();
    let (out, used) = compress_payload(&big, TYPE_OFF, DEFAULT_MIN_SIZE);
    assert_eq!(used, TYPE_OFF);
    assert_eq!(out.as_ref(), big.as_slice());

    // A zero min size means the default floor, not "compress everything".
    let (_, used) = compress_payload(small, TYPE_ZSTD, 0);
    assert_eq!(used, TYPE_OFF);
}

#[test]
fn off_decompress_is_passthrough_and_empty_is_fine() {
    let data = b"anything at all";
    let out = try_decompress_payload(data, TYPE_OFF).unwrap();
    assert_eq!(out.as_ref(), data.as_slice());

    let out = try_decompress_payload(&[], TYPE_ZSTD).unwrap();
    assert!(out.is_empty());
}

#[test]
fn corrupt_input_fails_cleanly() {
    // Garbage for each real codec returns None, never a panic.
    let garbage = [0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08];
    assert!(try_decompress_payload(&garbage, TYPE_ZSTD).is_none());
    assert!(try_decompress_payload(&garbage, TYPE_ZLIB).is_none());
    // LZ4 with a header claiming a size its tiny block cannot fill.
    let bad_lz4 = [0xff, 0xff, 0x00, 0x00, 0x00];
    assert!(try_decompress_payload(&bad_lz4, TYPE_LZ4).is_none());
}

#[test]
fn deflate_rejects_trailing_bytes() {
    // A valid DEFLATE stream with one extra byte appended must be rejected,
    // the way Go's `reader.Len() != 0` check does.
    let payload = repeated_1k();
    let mut good = deflate(&payload).unwrap();
    assert_eq!(inflate(&good).unwrap(), payload);
    good.push(0x00);
    assert!(inflate(&good).is_none());
}

#[test]
fn lz4_header_over_cap_is_refused() {
    // A header claiming more than the 10 MiB cap is refused before allocating.
    let mut framed = ((MAX_DECOMPRESSED_SIZE + 1) as u32).to_le_bytes().to_vec();
    framed.extend_from_slice(&[0u8; 8]);
    assert!(lz4_decompress(&framed).is_none());
}
